pub enum TestStatus {
    Passed,
    Failed,
    Exhausted,
    Inconclusive,
    Error,
    NotFailing,
}
#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Phase {
    Generation,
    Baseline,
    Shrink,
    Confirmation,
    Replay,
}
#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
